package com.ztna.model;

import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * Super Recovery Key Entity.
 * Represents a session-bound, short-lived, single-use key generated by an admin
 * to unlock a locked user account.
 * ONLY the cryptographic hash (SHA-256) is stored in the database.
 */
@Entity
@Table(name = "super_recovery_keys")
public class SuperRecoveryKey {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * Session token of the administrator who generated this recovery key.
     * Guarantees session-binding.
     */
    @Column(nullable = false)
    private String adminSessionId;

    @Column(nullable = false)
    private String adminUsername;

    @Column(nullable = false)
    private String targetUsername;

    /**
     * SHA-256 cryptographic hash of the 4-digit key.
     * Plaintext key is NEVER persisted or logged.
     */
    @Column(nullable = false)
    private String hashedKey;

    @Column(nullable = false)
    private LocalDateTime expiresAt;

    private boolean used = false;

    private LocalDateTime usedAt;

    private LocalDateTime createdAt = LocalDateTime.now();

    public SuperRecoveryKey() {}

    public SuperRecoveryKey(String adminSessionId, String adminUsername, String targetUsername,
                            String hashedKey, LocalDateTime expiresAt) {
        this.adminSessionId = adminSessionId;
        this.adminUsername = adminUsername;
        this.targetUsername = targetUsername;
        this.hashedKey = hashedKey;
        this.expiresAt = expiresAt;
        this.used = false;
        this.createdAt = LocalDateTime.now();
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getAdminSessionId() { return adminSessionId; }
    public void setAdminSessionId(String adminSessionId) { this.adminSessionId = adminSessionId; }

    public String getAdminUsername() { return adminUsername; }
    public void setAdminUsername(String adminUsername) { this.adminUsername = adminUsername; }

    public String getTargetUsername() { return targetUsername; }
    public void setTargetUsername(String targetUsername) { this.targetUsername = targetUsername; }

    public String getHashedKey() { return hashedKey; }
    public void setHashedKey(String hashedKey) { this.hashedKey = hashedKey; }

    public LocalDateTime getExpiresAt() { return expiresAt; }
    public void setExpiresAt(LocalDateTime expiresAt) { this.expiresAt = expiresAt; }

    public boolean isUsed() { return used; }
    public void setUsed(boolean used) { this.used = used; }

    public LocalDateTime getUsedAt() { return usedAt; }
    public void setUsedAt(LocalDateTime usedAt) { this.usedAt = usedAt; }

    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }
}
